#if _display_railways == 1
LAYER
    GROUP "default"
    STATUS ON
    CONNECTIONTYPE POSTGIS
    PROJECTION
        "init=epsg:OSM_SRID"
    END
    CONNECTION "OSM_DB_CONNECTION"
#if OSM_FORCE_POSTGIS_EXTENT == 1
    EXTENT OSM_EXTENT
#endif
    MINSCALEDENOM _minscale
    MAXSCALEDENOM _maxscale
    TYPE LINE
    NAME layername(railways,_layer_suffix)
    COMPOSITE
     OPACITY _railway_opacity
    END # COMPOSITE
    DATA _railways_data
    CLASSITEM "tunnel"
    CLASS
      EXPRESSION "0"
        STYLE
         WIDTH _railway_width
         COLOR _railway_clr
         OUTLINEWIDTH _railway_ol_width
         OUTLINECOLOR _railway_ol_clr
         PATTERN _railway_pattern END
         LINECAP BUTT
        END
    END
    CLASS
        STYLE
         WIDTH _railway_width
         COLOR _railway_clr
         PATTERN _railway_pattern END
         OPACITY _railway_tunnel_opacity
         LINECAP BUTT
        END
    END
END
#endif

#if _display_subway == 1
LAYER
    GROUP "default"
    STATUS ON
    CONNECTIONTYPE POSTGIS
    PROJECTION
        "init=epsg:OSM_SRID"
    END
    CONNECTION "OSM_DB_CONNECTION"
#if OSM_FORCE_POSTGIS_EXTENT == 1
    EXTENT OSM_EXTENT
#endif
    MINSCALEDENOM _minscale
    MAXSCALEDENOM _maxscale
    TYPE LINE
    NAME layername(subway,_layer_suffix)
    COMPOSITE
     OPACITY _subway_opacity
    END # COMPOSITE
    DATA _subway_data
    CLASSITEM "tunnel"
    CLASS
      EXPRESSION "0"
        STYLE
         WIDTH _subway_width
         COLOR _subway_clr
         OUTLINEWIDTH _subway_ol_width
         OUTLINECOLOR _subway_ol_clr
#if _subway_pattern != 0
         PATTERN _subway_pattern END
#endif
         LINECAP BUTT
        END
    END
    CLASS
        STYLE
         WIDTH _subway_width
         COLOR _subway_clr
#if _subway_pattern != 0
         PATTERN _subway_pattern END
#endif
         OPACITY _subway_tunnel_opacity
         LINECAP BUTT
        END
    END
END
#endif

#if _display_highways == 1

LAYER
    GROUP "default"
    STATUS ON
    TYPE LINE
    MINSCALEDENOM _minscale
    MAXSCALEDENOM _maxscale
    NAME layername(roads,_layer_suffix)
    COMPOSITE
     OPACITY _roads_opacity
    END # COMPOSITE
    PROJECTION
        "init=epsg:OSM_SRID"
    END
    CONNECTIONTYPE postgis
    CONNECTION "OSM_DB_CONNECTION"
#if OSM_FORCE_POSTGIS_EXTENT == 1
    EXTENT OSM_EXTENT
#endif
    DATA _roads_data
    LABELITEM "name"

########################################
## small roads, no tunnels or bridges ##
########################################

#if _display_other_roads == 1
    CLASS
#if _display_bridges == 1
        EXPRESSION ("[type]" IN "unclassified,residential,road,living_street" AND "[bridge]" = "0" AND "[tunnel]" = "0")
#else
        EXPRESSION ("[type]" IN "unclassified,residential,service,road,living_street")
#endif
#if _display_other_outline
        STYLE
           WIDTH _other_width
           OUTLINEWIDTH _other_ol_width
           OUTLINECOLOR _other_ol_clr
        END
#endif
        STYLE
            WIDTH _other_width
            COLOR _other_clr
        END
#if _label_other_roads == 1
        LABEL
            TYPE TRUETYPE
            PARTIALS FALSE
            FONT _other_font
            SIZE _other_lbl_size
            MINDISTANCE 200
            REPEATDISTANCE 400
            ANGLE FOLLOW
            COLOR _other_lbl_clr
#if _label_outline_other_roads == 1
            OUTLINECOLOR _other_lbl_ol_clr
            OUTLINEWIDTH _other_lbl_ol_width
#endif
            ENCODING "UTF-8"
            MINFEATURESIZE AUTO
            BUFFER 3
        END
#endif
    END
#endif





