            ANGLE FOLLOW
            COLOR _other_lbl_clr
#if _label_outline_other_roads == 1
            OUTLINECOLOR _other_lbl_ol_clr
            OUTLINEWIDTH _other_lbl_ol_width
#endif
            ENCODING "UTF-8"
            MINFEATURESIZE AUTO
            BUFFER 3
        END
#endif
    END
    CLASS
        EXPRESSION ("[type]" = "service" AND "[service]" IN "driveway,drive_through")
        STYLE
            WIDTH _driveway_width
            COLOR _driveway_clr
#if _display_driveway_outline
            OUTLINEWIDTH _driveway_ol_width
            OUTLINECOLOR _driveway_ol_clr
#endif
        END
#if _label_other_roads == 1
        LABEL
            TYPE TRUETYPE
            PARTIALS FALSE
            FONT _other_font
            SIZE _other_lbl_size
            MINDISTANCE 200
            REPEATDISTANCE 400
            ANGLE FOLLOW
            COLOR _other_lbl_clr
#if _label_outline_other_roads == 1
            OUTLINECOLOR _other_lbl_ol_clr
            OUTLINEWIDTH _other_lbl_ol_width
#endif
            ENCODING "UTF-8"
            MINFEATURESIZE AUTO
            BUFFER 3
        END
#endif
    END
    CLASS
        EXPRESSION ("[type]" = "service" AND "[service]" != "" AND NOT("[service]" IN "parking_aisle,alley,driveway,drive_through"))
        STYLE
            WIDTH _other_service_width
            COLOR _other_service_clr
#if _display_other_service_outline
            OUTLINEWIDTH _other_service_ol_width
            OUTLINECOLOR _other_service_ol_clr
#endif
        END
#if _label_other_roads == 1
        LABEL
            TYPE TRUETYPE
            PARTIALS FALSE
            FONT _other_font
            SIZE _other_lbl_size
            MINDISTANCE 200
            REPEATDISTANCE 400
            ANGLE FOLLOW
            COLOR _other_lbl_clr
#if _label_outline_other_roads == 1
            OUTLINECOLOR _other_lbl_ol_clr
            OUTLINEWIDTH _other_lbl_ol_width
#endif
            ENCODING "UTF-8"
            MINFEATURESIZE AUTO
            BUFFER 3
        END
#endif
    END
#endif

END


#if _display_oneway_arrows == 1
LAYER
    GROUP "default"
    STATUS ON
    MINSCALEDENOM _minscale
    MAXSCALEDENOM _maxscale
    TYPE LINE
    NAME layername(oneway_arrows,_layer_suffix)
    PROJECTION
        "init=epsg:OSM_SRID"
    END
    CONNECTIONTYPE postgis
    CONNECTION "OSM_DB_CONNECTION"
#if OSM_FORCE_POSTGIS_EXTENT == 1
    EXTENT OSM_EXTENT
#endif
    DATA _oneway_arrow_data
    PROCESSING "CLOSE_CONNECTION=DEFER"
    CLASS
        ## Accept both oneway=1 (forward) and oneway=-1 (backward)
        EXPRESSION ("[oneway]" = "1" OR "[oneway]" = "-1")
        STYLE
            SYMBOL "oneway_arrow"
            SIZE _oneway_arrow_size
            COLOR _oneway_arrow_clr
            GAP _oneway_arrow_gap
            ANGLE AUTO
        END
    END
END
#endif


#if _display_aeroways == 1
LAYER
    GROUP "default"
    STATUS ON
    MINSCALEDENOM _minscale
    MAXSCALEDENOM _maxscale
    TYPE LINE
    NAME layername(aeroways,_layer_suffix)
    PROJECTION
        "init=epsg:OSM_SRID"
    END
    CONNECTIONTYPE postgis
    CONNECTION "OSM_DB_CONNECTION"
#if OSM_FORCE_POSTGIS_EXTENT == 1
    EXTENT OSM_EXTENT
#endif
    COMPOSITE
     OPACITY _aeroways_opacity
    END # COMPOSITE
    DATA "geometry from (select geometry, osm_id, type from OSM_SCHEMA.OSM_PREFIX_aeroways) as foo using unique osm_id using srid=OSM_SRID"
    CLASSITEM "type"
    CLASS
      EXPRESSION "runway"
      STYLE
        COLOR _runway_clr
        WIDTH _runway_width
        LINECAP BUTT
        LINEJOIN MITER
      END
      STYLE
        COLOR _runway_center_clr
        WIDTH _runway_center_width
        PATTERN _runway_center_pattern END
        LINECAP BUTT
      END
    END
    CLASS
      EXPRESSION "taxiway"
      STYLE
        COLOR _taxiway_clr
        WIDTH _taxiway_width
      END
    END
END
#endif
#endif
